const listAccessibleProjects = `-- name: ListAccessibleProjects :many
SELECT pa.project_id FROM project_access pa
JOIN projects p ON p.id = pa.project_id
WHERE pa.user_id = $1 AND p.workspace_id = $2
`

type ListAccessibleProjectsParams struct {
	UserID      string
	WorkspaceID string
}

func (q *Queries) ListAccessibleProjects(ctx context.Context, arg ListAccessibleProjectsParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, listAccessibleProjects, arg.UserID, arg.WorkspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var project_id string
		if err := rows.Scan(&project_id); err != nil {
			return nil, err
		}
		items = append(items, project_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listActiveSessions = `-- name: ListActiveSessions :many
SELECT id, token_hash, user_id, user_agent, created_at, last_seen_at, expires_at, revoked_at, ip, method FROM sessions
WHERE user_id = $1 AND revoked_at IS NULL AND expires_at > $2
ORDER BY last_seen_at DESC
`

type ListActiveSessionsParams struct {
	UserID string
	Now    time.Time
}

func (q *Queries) ListActiveSessions(ctx context.Context, arg ListActiveSessionsParams) ([]Session, error) {
	rows, err := q.db.QueryContext(ctx, listActiveSessions, arg.UserID, arg.Now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Session
	for rows.Next() {
		var i Session
		if err := rows.Scan(
			&i.ID,
			&i.TokenHash,
			&i.UserID,
			&i.UserAgent,
			&i.CreatedAt,
			&i.LastSeenAt,
			&i.ExpiresAt,
			&i.RevokedAt,
			&i.Ip,
			&i.Method,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

