const upsertPushSubscription = `-- name: UpsertPushSubscription :exec

INSERT INTO push_subscriptions (id, user_id, session_id, endpoint, p256dh, auth, user_agent, created_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (endpoint) DO UPDATE SET user_id = excluded.user_id, session_id = excluded.session_id,
    p256dh = excluded.p256dh, auth = excluded.auth, user_agent = excluded.user_agent, warned_at = NULL
`

type UpsertPushSubscriptionParams struct {
	ID        string
	UserID    string
	SessionID string
	Endpoint  string
	P256dh    string
	Auth      string
	UserAgent string
	Now       time.Time
}

// Web push subscriptions. A subscription is live while the session that
// made it is.
// The same browser subscribing again (on another account, or with new
// keys) takes over its row.
func (q *Queries) UpsertPushSubscription(ctx context.Context, arg UpsertPushSubscriptionParams) error {
	_, err := q.db.ExecContext(ctx, upsertPushSubscription,
		arg.ID,
		arg.UserID,
		arg.SessionID,
		arg.Endpoint,
		arg.P256dh,
		arg.Auth,
		arg.UserAgent,
		arg.Now,
	)
	return err
}

const upsertUserTheme = `-- name: UpsertUserTheme :execrows
INSERT INTO user_themes (id, user_id, name, body, created_at, updated_at)
VALUES ($1, $2, $3, $4, $5, $5)
ON CONFLICT (id) DO UPDATE SET name = excluded.name, body = excluded.body, updated_at = excluded.updated_at
WHERE user_themes.user_id = excluded.user_id
`

type UpsertUserThemeParams struct {
	ID     string
	UserID string
	Name   string
	Body   string
	Now    time.Time
}

// Writes a theme, keeping when it was made. Someone else's id changes
// nothing: no rows, which the caller answers as not found.
func (q *Queries) UpsertUserTheme(ctx context.Context, arg UpsertUserThemeParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, upsertUserTheme,
		arg.ID,
		arg.UserID,
		arg.Name,
		arg.Body,
		arg.Now,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

